import{_ as e,a0 as s,w as r,s as p,I as i,x as n,a1 as u,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Linux 桌面的發展之路 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 桌面的發展之路 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 桌面的發展之路 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 桌面的發展之路 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/Improving The Linux Desktop","title":"Linux 桌面的發展之路","tag":"201405","desc":""},"relativePath":"201405/Improving The Linux Desktop.md","filePath":"[post].md"}'),x={name:"201405/Improving The Linux Desktop.md"};function L(m,t,d,f,a,T){const o=s("Link");return r(),p("div",null,[t[17]||(t[17]=i("h1",{id:"linux-桌面的發展之路",tabindex:"-1"},[n("Linux 桌面的發展之路 "),i("a",{class:"header-anchor",href:"#linux-桌面的發展之路","aria-label":"Permalink to “Linux 桌面的發展之路”"},"​")],-1)),i("p",null,[t[1]||(t[1]=n("Ken Starks 在 fossforce.com 網站上問 ",-1)),u(o,{href:"http://fossforce.com/2014/04/what-would-you-do-to-improve-linux/"},{default:l(()=>[...t[0]||(t[0]=[n("你們是如何優化 Linux 的？",-1)])]),_:1}),t[2]||(t[2]=n("，我很高興他問了這個問題，因為我有話要説！對我來説，Linux 桌面就是一連串的承諾，但是這些承諾卻總是無法兑現。它在每個版本發佈後都會説“下個版本會非常牛X”，=.=凸。它會一次性定下50個目標，然後又完成不了幾個。至於 Linux 桌面，我想我們是時候好好聊聊這玩意兒了。",-1))]),t[18]||(t[18]=i("p",null,"計算機有着無窮的魅力，在計算機的世界裏我們幾乎能做所有事情。在這個容易迷失的世界裏，我們深信自己所着迷的事情對其他人也有着相同的吸引力。我們沉迷於鑽研細節，爭論 GPL 和 LGPL 的區別，討論為什麼我們稱“Linux”為“GNU/Linux”而不是簡單的“Linux”，諸如此類，我們總想説服別人，推銷自己喜歡的 Linux 桌面風格。我們總是説“這關乎自由，瞧瞧蘋果是怎麼限制你的選擇的！”卻從來沒意識到那些選擇了不同計算機系統的用户僅僅是把計算機當作工作所需的工具而已。對於我們來説，計算機有點兒像變戲法，當第一次動手修改一些重要配置，改變計算機的工作方式時，我們會非常激動，非常有成就感。在開源界，你是這個世界的主宰，你沉迷於控制一切。然而，對於那些沒有準備好掌握這種控制一切的力量的人來説，開源社區並不是他們的菜。",-1)),t[19]||(t[19]=i("p",null,"大多數工程師並不是設計師，但開源社區能讓這些開發者成為一些圖形交互界面的設計者。於是，我們的 Unity 不再顯示主菜單，我們的 Gnome 3 窗口可以満屏幕亂飛，而 KDE 桌面，我一直覺得它完全無法理解，所以我已經好多年沒關注它了（在這裏向 KDE 開發團隊和其支持者表示道歉，我無法理解 KDE 是好幾年前的事了，我相信現在的 KDE 肯定能用 awesome 來形容）。前面提到的在 fossforce.com 網站上的那篇文章提了一個很好的問題：為什麼 Linux 桌面總是不能像人們所希望的那樣普及出來。而文章下面的評論則是一堆社區成員的抱怨和建議，比如：讓窗口更好地整合在一起；讓添加磁盤變得更簡單些。很多評論都是很好的、可行的建議，但他們大多數都忽略了一個核心事實：是什麼讓 Linux 成為一個既精彩但又前途暗淡的、只屬於狂熱愛好者的系統？Linux 發行版是由非常多的軟件包組成的，每個軟件包都有不同的維護者，不同的價值和不同的開發過程。當每個開發團隊將他們的產品通過開源社區貢獻出來時，每個開發團隊會變得只有一點點不一樣，而僅僅是這一點點的不一樣，讓我們對細枝末節的探索有了發揮的餘地。有些人不喜歡 Ubuntu 桌面，於是他們克隆 Ubuntu，在上面作一些細微的改變，然後重新發佈一個衍生版。這種方式挺不錯的，因為它能帶來新點子，向人們展示一個事物能夠變成什麼樣子 —— 即使是很小的改變。但是每當新產生一個衍生版，就會將開源社區變得更碎片化一些。這到底是好事還是壞事？看你是站在什麼角度來看。",-1)),t[20]||(t[20]=i("p",null,"Linux 桌面是建立在成千上萬的軟件基礎之上的，每個軟件由不同團隊維護。有時候我們會想這樣的東西究竟能不能工作？！事實是，它能，並且工作得非常好，這真是一個奇蹟。然而有時候它又不工作了，它會崩潰，在這種時候我們就會列出一連串的計劃來改進 Linux，並將我們最不能忍受的缺陷放在計劃的最前面。",-1)),t[21]||(t[21]=i("p",null,"經過上面的討論，我的建議出來了。第一點：繼續做你正在做的事。技術總是能反映創造者的價值，而 Linux 桌面更是一個多國家多文化集合的體現。Linux 充滿缺陷，充滿傷痕，但也是因為這些，令它變得美好。世界需要現在的 Linux 桌面，同時世界需要更好的 Linux 桌面。",-1)),t[22]||(t[22]=i("p",null,"第二點：選一個發行版，比如 Ubuntu，弄爛它。然後，拾起一些碎片，在這些碎片上創造一些全新的東西。不要從社區獲取軟件或者產品，只需要獲取想法。從內核開始，一個團隊，一個房間，一種設計理念和設計哲學，從頭創建一整個操作系統。將注意力集中在那些最好的已經實現的想法上，以及那些最新的還沒實現的想法上。丟掉所有糟糕的東西，創造全新的東西。",-1)),i("p",null,[t[4]||(t[4]=n("到目前為止，我見過的最接近這種觀念的是 Aral Balkan 開發的 ",-1)),u(o,{href:"http://indiephone.eu/"},{default:l(()=>[...t[3]||(t[3]=[n("Indie",-1)])]),_:1}),t[5]||(t[5]=n(" 項目，但他最近貌似專注於移動市場。我希望 Linux 桌面朝着這種觀念靠近。這有可能麼？當然，一切皆有可能。但確定會發生麼？誰知道呢？整個 Linux 生態系統都充滿不確定性。唯一確定的是，我們的創造性是無限的。",-1))]),t[23]||(t[23]=i("hr",null,null,-1)),i("p",null,[t[7]||(t[7]=n("via: ",-1)),u(o,{href:"http://ostatic.com/blog/improving-the-linux-desktop"},{default:l(()=>[...t[6]||(t[6]=[n("http://ostatic.com/blog/improving-the-linux-desktop",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=n("譯者：",-1)),u(o,{href:"https://github.com/bazz2"},{default:l(()=>[...t[8]||(t[8]=[n("bazz2",-1)])]),_:1}),t[11]||(t[11]=n(" 校對：",-1)),u(o,{href:"http://blog.csdn.net/tinyeyeser"},{default:l(()=>[...t[9]||(t[9]=[n("Mr小眼兒",-1)])]),_:1})]),i("p",null,[t[14]||(t[14]=n("本文由 ",-1)),u(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[12]||(t[12]=[n("LCTT",-1)])]),_:1}),t[15]||(t[15]=n(" 原創翻譯，",-1)),u(o,{href:"http://linux.cn/"},{default:l(()=>[...t[13]||(t[13]=[n("Linux中國",-1)])]),_:1}),t[16]||(t[16]=n(" 榮譽推出",-1))])])}const D=e(x,[["render",L]]);export{k as __pageData,D as default};
